def bands(m: int, texts) -> str:
    n = len(texts)
    edges = [round(m * i / n) for i in range(n + 1)]
    out = ['0: does not reach a standard described by the descriptors below']
    for i in range(n):
        lo, hi = edges[i] + 1, edges[i + 1]
        if lo > hi:
            continue
        out.append(f'{lo}–{hi}: {texts[i]}' if lo != hi else f'{hi}: {texts[i]}')
    return 'Markbands – ' + '; '.join(reversed(out)) + '.'


def lc(s: str) -> str:
    w = s.split(' ')[0]
    return s[0].lower() + s[1:] if w in LOWERABLE else s


