def _blk(lab, s):
    return f'Source {lab}\n{s[0]}\n— {s[1]}'


def source_templates(key: str, d: dict) -> list:
    src, topic, cmp_, ev, essays = d['src'], d['topic'], d['cmp'], d['ev'], d['essays']
    texts = [s for s in src if len(s) < 6]
    visuals = [s for s in src if len(s) >= 6] or src
    out = []

    def q1a(rng, slot):
        s = rng.choice(texts or src)
        lab = rng.choice(LABELS)
        m = slot.marks or 3
        q = rng.choice([
            f'According to Source {lab}, what can be learned about {topic}?',
            f'Identify three points made in Source {lab} about {topic}.',
            f'What, according to Source {lab}, were the main features of {topic}?',
        ])
        if slot.set == 'mock':  # mock-only frames, worded apart so they never collide with bank items or each other
            q = rng.choice(MOCK_Q['q1a']).format(L=lab, T=topic)
        return dict(stem=f'{_blk(lab, s)}\n\n{q} [{m}]', answer=s[2], type='case', marks=m, minutes=float(2.5 * m),
                    markingKey=f'{s[2]} Award 1 mark for each relevant point drawn from the source, up to [{m}]. '
                               'Points must be taken from the source; own knowledge is not credited in Question 1.', gap='G7')
    out.append(T('C3', (1, 3), q1a, 'case', 'p1q1a', 'p1q1a'))

    def q1b(rng, slot):
        s = rng.choice(src if slot.set == 'mock' else visuals)
        lab = rng.choice(LABELS)
        m = slot.marks or 2
        q = rng.choice([f'What is the message conveyed by Source {lab}?',
                        f'What is the message of Source {lab} about {topic}?',
                        f'Outline the message that the author of Source {lab} intended to convey.'])
        if slot.set == 'mock':
            q = rng.choice(MOCK_Q['q1b']).format(L=lab, T=topic)
        return dict(stem=f'{_blk(lab, s)}\n\n{q} [{m}]', answer=s[2], type='case', marks=m, minutes=float(2.5 * m),
                    markingKey=f'{s[2]} Award 1 mark for each valid point about the message, up to [{m}]; a description of the '
                               'source without interpretation of its message scores at most 1.', gap='G7')
    out.append(T('C3', (1, 3), q1b, 'case', 'p1q1b', 'p1q1b'))

    def opvl(rng, slot):
        s = rng.choice(src)
        lab = rng.choice(LABELS)
        m = slot.marks or (4 if slot.d >= 3 else 3)
        q = rng.choice([
            f'With reference to its origin, purpose and content, analyse the value and limitations of Source {lab} for an historian studying {topic}.',
            f'With reference to the origin, purpose and content of Source {lab}, assess its values and limitations for historians investigating {topic}.',
        ])
        if slot.set == 'mock':
            q = rng.choice(MOCK_Q['q2']).format(L=lab, T=topic)
        return dict(stem=f'{_blk(lab, s)}\n\n{q} [{m}]', answer=f'Value: {s[3]} Limitations: {s[4]}', type='case', marks=m,
                    minutes=float(2.5 * m),
                    markingKey=f'Value: {s[3]} Limitations: {s[4]} Award up to [{m}]: origin, purpose and content must each be '
                               'referred to and linked to value or limitation for the stated enquiry. If only values or only '
                               'limitations are discussed, award a maximum of [2]. Listing provenance without explaining its '
                               'effect on value is not rewarded.', gap='G7')
    out.append(T(('C3', 'C4'), (2, 5), opvl, 'case', 'p1q2', 'p1q2'))

    if len(src) >= 2 and cmp_:
        def compare(rng, slot):
            if slot.set != 'mock':
                return None  # each source pair yields one distinct stem: keep it for the mock papers
            la, lb = rng.choice([('A', 'B'), ('B', 'C'), ('C', 'D'), ('A', 'C')])
            m = slot.marks or 6
            q = rng.choice(MOCK_Q['q3']).format(A=la, B=lb, T=topic)
            return dict(stem=f'{_blk(la, src[0])}\n\n{_blk(lb, src[1])}\n\n{q} [{m}]', answer=cmp_, type='case', marks=m,
                        minutes=float(2.5 * m),
                        markingKey=f'{cmp_} Award 1 mark per valid, explicitly linked point of comparison or contrast, up to [{m}]. '
                                   'If only comparisons or only contrasts are offered, award a maximum of [4]. A running '
                                   '(integrated) comparison is preferred to end-on description; provenance is not compared here.', gap='G7')
        out.append(T('C4', (3, 5), compare, 'case', 'p1q3', 'p1q3'))

    if len(src) >= 2 and ev:
        def synth(rng, slot):
            if slot.set != 'mock':
                return None
            claim, pro, con, judge = rng.choice(ev)
            m = slot.marks or 9
            la, lb = rng.choice([('A', 'B'), ('A', 'D'), ('B', 'C'), ('C', 'D')])
            q = rng.choice(MOCK_Q['q4']).format(c=lc(claim), c2=lc(claim).rstrip('.'))
            stem = f'{_blk(la, src[0])}\n\n{_blk(lb, src[1])}\n\n{q} [{m}]'
            key = ('Indicative content – supporting: ' + '; '.join(pro) + '. Challenging: ' + '; '.join(con) +
                   f'. Judgement: {judge} Responses must use both sources and accurate own knowledge. ' + bands(m, Q4_BANDS))
            return dict(stem=stem, answer=judge, markingKey=key, type='long', marks=m, minutes=float(2.5 * m), gap='G5')
        out.append(T('C4', (3, 5), synth, 'long', 'p1q4', 'p1q4'))

    def essay_maker(paper):
        def essay(rng, slot):
            m = slot.marks or 15
            pool = [('E', e) for e in essays] + [('V', e) for e in ev]
            if not pool:
                return None
            kind, e = rng.choice(pool)
            if kind == 'E':
                stem, pts, judge = e
                pro, con = pts, []
                if paper == 'p3' and rng.random() < 0.5:
                    stem = 'With reference to the period and region you have studied in depth: ' + lc(stem)
            else:
                claim, pro, con, judge = e
                if paper == 'p2':
                    stem = rng.choice([f'"{claim}" With reference to specific examples, discuss.',
                                       f'To what extent do you agree that {lc(claim).rstrip(".")}?',
                                       f'Examine the view that {lc(claim)} Refer to at least two examples in your answer.'])
                else:
                    stem = rng.choice([f'"{claim}" How far do you agree with this statement?',
                                       f'Evaluate the validity of the view that {lc(claim)}',
                                       f'With reference to the history of the region, discuss the claim that {lc(claim)}'])
            if slot.set == 'mock':  # mock-only wording so the papers never repeat a bank stem
                if kind == 'E':
                    stem = rng.choice(MOCK_E['E_' + paper]).format(q=e[0], q_lc=lc(e[0]))
                else:
                    stem = rng.choice(MOCK_E[paper]).format(C=e[0], c=lc(e[0]), c2=lc(e[0]).rstrip('.'))
            label = 'Paper 2' if paper == 'p2' else 'Paper 3'
            key = (f'{label} essay. Indicative content: ' + '; '.join(list(pro) + list(con)) +
                   f'. A strong answer reaches a judgement such as: {judge} ' + bands(m, ESSAY_BANDS))
            mins = 45.0 if paper == 'p2' else 50.0
            return dict(stem=f'{stem} [{m}]', answer=judge, markingKey=key, type='long', marks=m, minutes=mins, gap='G5')
        return essay
    out.append(T('C4', (3, 5), essay_maker('p2'), 'long', 'p2', 'essay_p2'))
    out.append(T('C4', (4, 5), essay_maker('p3'), 'long', 'p3', 'essay_p3'))
    return out


def H(key, topic, terms=(), facts=(), why=(), contrast=(), misc=(), cases=(), src=(), cmp='', ev=(), essays=(),
      apply=(), extended=()):
    R.facts(key, F(terms=list(terms), facts=list(facts), why=list(why), contrast=list(contrast), misc=list(misc),
                   apply=list(apply), cases=list(cases), evaluate=list(ev), extended=list(extended)))
    SRC[key] = dict(topic=topic, src=list(src), cmp=cmp, ev=list(ev), essays=list(essays))


