KEEP_CAPS = {'Manchukuo', 'Japan', 'Hitler’s', 'Mussolini’s', 'Germany', 'Czechoslovakia', 'Italy', 'Italy’s', 'Khrushchev',
             'Kennedy', 'Kennedy’s', 'Castro', 'Khrushchev’s', 'Reagan’s', 'Gorbachev', 'Sun', 'Japanese', 'Korea', 'Mao’s',
             'Deng', 'Deng’s', 'Britain', 'Jinnah', 'Nehru’s', 'Bangladesh’s', 'NATO', 'Paper', 'Section', 'Question', 'At',
             'Post-revisionist', 'Non-superpower', 'Non-alignment'}


def _restore_caps(fn, fixes):
    # _common lower-cases the first letter of a claim when it is embedded in a frame; undo that for proper nouns
    def wrapped(rng, slot):
        out = fn(rng, slot)
        if out:
            for low, orig in fixes:
                out['stem'] = out['stem'].replace(low, orig)
        return out
    return wrapped


def templates(st):
    key = st['id'].rsplit('-', 2)[-2] + '-' + st['id'].rsplit('-', 1)[-1]
    out = R.build(st, STYLE)
    f = R.f.get(key)
    fixes = []
    if f:
        for claim in [c[0] for c in f.evaluate] + [c[0] for c in f.misc]:
            w = claim.split(' ')[0]
            if w in KEEP_CAPS and w not in ('At', 'Post-revisionist', 'Non-superpower', 'Non-alignment'):
                fixes.append((claim[0].lower() + claim[1:30], claim[:30]))
            elif w not in KEEP_CAPS:  # ordinary sentence start embedded after "that": lower-case it
                fixes.append((' that ' + claim[:30], ' that ' + claim[0].lower() + claim[1:30]))
    if fixes:
        out = [T(t.c, t.d, _restore_caps(t.fn, fixes), t.type, t.style, t.name) for t in out]
    if key in SRC:
        out += source_templates(key, SRC[key])
    return out

